// Texto del cuerpo de Valuación (español e inglés). Todas las cifras salen de comun/cifras.js (modelo de valoración v4),
// de modo que el texto, las figuras y los anexos no pueden contradecirse. Las figuras locales se numeran 27–34 y las
// renumera informe_final.js; F7 (capex), T (tornado de Riesgos) y R1–R3 (Resumen de inversión) son citas a otras secciones.
const cifras = require("../../comun/cifras");

const pbReal = (K) => Math.round((K.tir.firma.real - K.kd_real) * 1e4);

function calcular(lang) {
  const { K, f } = cifras(lang);
  const es = lang === "es", s = K.s, E = K.esc, TIR = K.tir, TP = K.tir_proyecto, S = K.sens;
  const abs = Math.abs;
  const capexTot = s.capex_base.map((x, i) => abs(x) + abs(s.capex_exp[i]));
  const pipe = s.capex_proy.slice(0, 3).reduce((a, b) => a + b, 0);
  const mant = s.mant.slice(1), expc = s.capex_exp.slice(2, 6).map(abs), ct = s.ct.slice(1, 6).map(abs);
  const rng = (a, d = 0, div = 1000) => `${f.n(Math.min(...a) / div, d)}–${f.n(Math.max(...a) / div, d)}`;
  const imax = capexTot.indexOf(Math.max(...capexTot.slice(0, 6)));
  const anio = ["2S26E", "2027E", "2028E", "2029E", "2030E", "2031E"][imax];
  const capexIng = [3, 4, 5].map((i) => capexTot[i] / s.ing[i]);
  const dNueva = s.dfn_cierre[5] - K.dfn_mm;
  const ffoCagr = Math.pow(s.ffo[2] / s.ffo[0], 1 / 2) - 1;
  const cascadaFin = K.supuestos_acum[K.supuestos_acum.length - 1];
  const ratioPS = S.ssr_1pp / S.sss_1pp;
  const d4111 = K.consenso.po_12m / (1 + K.ke_t);
  const goodwillPct = abs(K.supuestos_indiv[6][1]) / K.supuestos_base * 100;
  const kdPO = K.supuestos_base + K.supuestos_indiv[5][1];            // objetivo con la tasa efectiva de la última emisión
  const ctCero = K.supuestos_indiv[2][1] / K.supuestos_base * 100;
  const po30s = K.po * 2118 / 2075.73;                                // DCF llevado al 30-sep-26 (mismo factor que en la versión anterior)
  const e = (k) => E[k];
  const T = {
    // ------------------------------------------------------------------ español
    es: {
      lead: `Recomendamos VENDER Mallplaza con un precio objetivo de CLP ${f.n(K.po)} por acción, ${f.pc(abs(K.po_vs), 1)} bajo el cierre de CLP ${f.n(K.precio)} del 30-sep-26 (${f.pc(K.ret_total, 1)} de retorno total con dividendos). Nuestro precio objetivo queda incluso bajo el mínimo de las últimas 52 semanas (CLP ${f.n(K.rango_52s[0])}).`,
      p1: [
        { h1: "UN PRECIO QUE NINGÚN MÉTODO ALCANZA" },
        { p: `En doce meses la acción subió de CLP ${f.n(K.rango_52s[0])} a ${f.n(K.rango_52s[1])} y hoy cotiza en CLP ${f.n(K.precio)}. Ninguno de nuestros métodos llega a ese precio: el DCF va de CLP ${f.n(K.football.dcf_100[0])} a ${f.n(K.football.dcf_100[1])} aun moviendo la WACC nominal ±100 pb y el g nominal entre 2,5% y 4,0%, y los múltiplos más favorables tampoco lo alcanzan (Figura 27). Damos 80% del peso al DCF porque Mallplaza es, en el fondo, un cobrador de arriendos: el 81,4% de sus ingresos son arriendos y el 93% de ellos es renta fija. El 20% en múltiplos contrasta el modelo con lo que el mercado paga hoy, pero con cautela: en Chile hay solo dos pares directos y ninguno captura el plan de expansión ni la trayectoria de deuda de la compañía.` },
        { p: `La Figura 27 resume la tesis en una imagen. El APV, que valora la empresa sin deuda y suma aparte los escudos fiscales, da CLP ${f.n(K.apv)}, apenas ${f.pc(K.apv / K.dcf - 1, 0)} sobre el DCF: el resultado no depende de cómo modelamos el financiamiento. Los múltiplos van de CLP ${f.n(K.football.mult_set_cl[0])} (mediana del set común) a ${f.n(K.football.mult_set_cl[1])} (mediana chilena), y el EV/EBITDA NTM y el EV/EBIT quedan entre CLP ${f.n(K.football.ntm_ebit[0])} y ${f.n(K.football.ntm_ebit[1])}. Todo cae a la izquierda del precio; lo único que lo alcanza es el propio rango de cotización del último año. Incluso la mediana chilena de múltiplos, el escenario más favorable para la acción, queda ${f.pc(abs(K.football.mult_set_cl[1] / K.precio - 1), 0)} bajo el precio.` },
        { h1: "LA HISTORIA ESTÁ EN LA TASA" },
        { p: `Proyectamos el flujo de caja libre de la firma (FCFF) en CLP nominales desde el 30-jun-26, con horizonte explícito hasta 2031E y un valor terminal que explica el ${f.pc(K.vt_ev, 0)} del EV (Anexo 15). Los CLP ${f.n(K.dcf)} por acción son CLP ${f.n(K.ps_exp)} de flujos explícitos y CLP ${f.n(K.ps_vt)} de valor terminal, menos CLP ${f.n(K.ps_deuda)} de deuda neta y minoritarios: el resultado depende, sobre todo, de la tasa de descuento.` },
        { p: `Esa tasa se mueve con la estructura de capital. Mallplaza usa su capacidad de deuda para crecer, como en 2024 tras comprar Open Plaza Perú (3,78x): suponemos que la DFN/EBITDA sube de ${f.n(K.dfn_ebitda0, 2)}x a ${f.n(K.dfn_ebitda_obj, 1)}x en 2031, con 25 pb más de costo real por cada vuelta, y que la deuda nueva (CLP ${f.bn(dNueva)} billones) financia todo el capex mientras la caja operativa se distribuye a los accionistas. Así, la WACC nominal pasa de ${f.pc(K.wacc_2s, 2)} en 2S26E a ${f.pc(K.wacc_t, 2)} en el terminal (${f.pc(K.wacc_2s_real, 2)} y ${f.pc(K.wacc_t_real, 2)} reales): un Ke nominal de ${f.pc(K.ke_t, 2)} (${f.pc(K.ke_t_real, 2)} real; Rf de ${f.pc(K.rf, 2)} en USD, beta re-apalancada de ${f.n(K.beta_t, 2)} desde una mediana de seis pares de ${f.n(K.beta_u, 2)}, ERP ${f.pc(K.erp, 2)} y CRP de ${f.pc(K.crp, 2)} ponderado por ingresos) y un Kd nominal de ${f.pc(K.kd_t_at, 2)} después de impuestos, basado en el cupón real de ${f.pc(K.kd_real, 1)} (UF) de la última emisión (Anexo 19).` },
        { p: `Construimos el Ke en dólares porque sus tres insumos están en esa moneda y son nominales: la Rf del Tesoro de EE.UU., la prima por riesgo de mercado implícita que publica Damodaran y el riesgo país, que ponderamos por ingresos. Luego lo llevamos a pesos con el diferencial entre la inflación esperada de Chile (3,0%, meta del BCCh) y la de EE.UU. (2,24%, breakeven a 10 años). La beta se desapalanca con Hamada (seis pares regionales) y se re-apalanca cada período (${f.n(K.beta_2, 2)} en 2S26E, ${f.n(K.beta_t, 2)} en el terminal).` },
        { p: `La primera señal es la TIR del activo (la firma): la tasa única que iguala el FCFF y el valor terminal al valor de empresa que paga el mercado a CLP ${f.n(K.precio)} (EV de CLP ${f.bn(K.ev_mercado_mm)} billones). Es ${f.pc(TIR.firma.nom, 2)} nominal (${f.pc(TIR.firma.real, 2)} real en UF), ${f.pb(TIR.firma.brecha_nom)} pb bajo la WACC nominal (${f.pb(TIR.firma.brecha_real)} pb en términos reales) y apenas ~${pbReal(K)} pb reales sobre el costo real de su deuda (Figura 28).` },
        { t: "TIR" },
        { h1: "CRECER NO RESCATA EL PRECIO" },
        { p: `No es que seamos pesimistas con la operación. Proyectamos un margen EBITDA de 79,7% en 2026E (sin revalorizaciones, bajo el 80,5% UDM), un impuesto en caja que converge de 16,8% a 27% en 2030, el pipeline completo con fecha de la compañía (${f.n(K.pipeline_m2)} m² y USD ${f.n(K.pipeline_usd_mm)} MM, incluidos ${f.n(K.otros_m2)} m² de «otros proyectos» en Chile que abren en 2028) y, desde 2029, ${f.n(K.gla_anual)} m² nuevos al año, el ritmo orgánico histórico. El consenso de 13 analistas espera un EBITDA a 12 meses apenas ~3% sobre el nuestro: la diferencia con el mercado no está en los flujos.` },
        { p: `El capex sigue el plan de la compañía y se separa en mantención y TI (5,5% de los ingresos, CLP ${rng(mant)} mil MM al año) y capex incremental: el pipeline en curso (CLP ${f.mm(pipe, 0)} mil MM en 2S26E–2028E) y la expansión continua (CLP ${rng(expc)} mil MM al año desde 2028, a USD ${f.n(K.costo_usd_m2)} por m² y con una rampa de ingresos de 35%, 90% y 100%). El capex total llega a un máximo de CLP ${f.mm(capexTot[imax], 0)} mil MM en ${anio} y se estabiliza cerca de ${f.pc(capexIng.reduce((a, b) => a + b, 0) / 3, 0)} de los ingresos desde 2029E (Figura F7). El capital de trabajo (15,6% de los ingresos) exige CLP ${f.n(Math.min(...ct) / 1000, 1)}–${f.n(Math.max(...ct) / 1000, 1)} mil MM al año y, si fuera cero, el objetivo subiría solo ${f.pc(ctCero / 100, 1)} (Figura 29; Anexo 16).` },
        { p: `Dos supuestos merecen una explicación. La tasa de impuesto en caja parte en 16,8% porque hoy la compañía usa goodwill tributario y pérdidas acumuladas; suponemos que esos escudos se agotan y que la tasa llega a 27% en 2030. Es ahorro de caja real (baja el impuesto corriente), no contable: CLP ${f.n(K.escudo_ps, 0)} por acción sin descontar; sin él el objetivo baja ${f.n(goodwillPct, 1)}% (Figura 29). Y el capital de trabajo crece con los ingresos, no con los m² nuevos.` },
        { p: `Precio y ventas. En un operador de arriendos el precio es el arriendo por m², y las ventas de los locatarios llegan al ingreso solo por la renta variable (${f.pc(S.share_var, 1)} de los ingresos). Por eso 1 pp más de crecimiento nominal del arriendo en mismas tiendas en 2027–28 agrega CLP ${f.n(S.ssr_1pp, 0)} al valor DCF por acción, ${f.n(ratioPS, 0)} veces lo que agrega 1 pp más de crecimiento de las ventas de los locatarios (CLP ${f.n(S.sss_1pp, 1)}); 1 pp más de crecimiento real del arriendo en 2029–31 agrega CLP ${f.n(S.ssr_lp_1pp, 0)}. Una mejora de precios puede traducirse en mayores ventas y renta variable cuando la ocupación y el tráfico la sostienen, así que en el escenario bull movemos ambas palancas a la vez (arriendo +9,4%, ventas +9,9%): aun así el precio objetivo queda ${f.pc(abs(e("bull").vs), 0)} bajo el precio.` },
        { p: `El problema es el retorno de crecer. Cada m² nuevo rinde ${f.pc(K.yield_costo, 1)} real antes de impuestos sobre su costo (mix de la expansión: ${f.pc(K.mix_chile, 0)} Chile, ${f.pc(1 - K.mix_chile, 0)} Perú), un RONIC real de ${f.pc(K.ronic, 1)} después de impuestos, bajo una WACC real de ${f.pc(K.wacc_t_real, 1)}. La TIR de un m² nuevo, con capex, rampa, mantención y capital de trabajo, es ${f.pc(TP.real, 2)} real (${f.pc(TP.nom, 2)} nominal): ${f.pb(TP.brecha_real)} pb bajo la WACC real y ${f.pb(TP.brecha_nom)} pb bajo la nominal; para igualarla, el ingreso por m² tendría que ser ${f.n(TP.escala_igualar_wacc, 2)} veces el del modelo. La expansión suma ingresos, pero no valor: por eso el valor terminal crece solo con la inflación (g de ${f.pc(K.g, 1)} nominal, 0% real) y un g mayor reduce el valor (Figura 30). Suponer más crecimiento no cerraría la brecha con el precio; la agrandaría. Por eso el horizonte explícito incluye el capex y la maduración de los proyectos que abren hasta 2032 (${f.n(K.m2_maduro)} m² maduran en el año terminal), pero desde ahí el capex incremental terminal es cero y solo queda la mantención.` },
        { h1: "¿POR QUÉ EXPANDIRSE SI NO CREA VALOR?" },
        { p: `Si crecer rinde menos que el costo de capital, ¿qué empuja a la administración a seguir? Planteamos cuatro hipótesis, por verificar con la memoria y los EEFF. Primero, contabilidad frente a economía: la deuda es 100% en UF a ~3,6% real, bajo lo que rinde un activo nuevo, así que cada proyecto financiado con deuda mejora FFO, EBITDA y utilidad aunque no cubra el retorno exigido al capital total. Segundo, la revalorización: bajo NIC 40 las tasaciones usan tasas reales de 5,5–6,4%, menores que la WACC, y cada activo nuevo se tasa sobre su costo y genera utilidad contable. Tercero, el controlador: si el grupo (Falabella, por confirmar) tiene tiendas ancla u otros negocios en esos malls, un m² nuevo le sirve al grupo aunque a Plaza le rinda poco, un conflicto de agencia con los minoritarios (por verificar en las notas de partes relacionadas). Cuarto, la compensación: si los bonos dependen del GLA o del EBITDA y no del ROIC, expandirse es racional para la gerencia (por verificar). Hay también razones estratégicas defendibles, como el suelo escaso y las ventajas de red. Es un riesgo de gobierno corporativo y de asignación de capital, y no contradice que el negocio sea bueno. El punto de equilibrio de la expansión es una WACC real de ${f.pc(K.ronic, 1)} (${f.pc((1 + K.ronic) * (1 + K.pi) - 1, 1)} nominal); la WACC implícita en el precio (${f.pc(K.wacc_impl, 2)} nominal, ${f.pc(K.wacc_impl_real, 1)} real) queda bajo ese nivel: si el mercado tuviera razón, expandir crearía valor.` },
      ],
      p2: [
        { h1: "LOS PARES CONFIRMAN LA DIRECCIÓN, NO LA MAGNITUD" },
        { p: `Mallplaza transa a 16,8x EV/EBITDA, sobre la mediana chilena (15,7x) y muy por encima de los pares brasileños (9,0x). La brecha con Brasil no es de calidad, sino de tasas: con bonos reales locales de 2,5% en Chile y 8,1% en Brasil (NTN-B), el spread del cap rate (rendimiento EBITDA/EV; con rentas reajustadas por UF se compara con tasas reales) sobre la tasa local es parecido en ambos países, 385 pb en Chile y 302 pb en Brasil (Figura 31). Por eso ponderamos 70% la mediana chilena y 30% la del set común (que incluye IRSA; excluimos Fibra Danhos por su régimen FIBRA): ${f.n(K.mult_x, 1)}x, que lleva a CLP ${f.n(K.mult_valor)} por acción. La ponderación pesa poco: entre 0% y 100% Chile, el precio objetivo solo va de CLP 1.916 a 2.144 (Anexo 17).` },
        { p: `Elegimos el set con el mismo criterio que la beta. IRSA se mantiene con cautela, porque reporta bajo NIC 29 y su consenso NTM tiene un solo analista; Fibra Danhos queda fuera porque, como FIBRA, debe repartir el 95% de su resultado fiscal y no tiene beta en la WACC. Usamos EV/EBITDA porque es neutral al apalancamiento y a la revalorización (NIC 40), y medimos a todos con la deuda neta de Bloomberg (CLP 1.311.569 MM para Mallplaza, cerca de los CLP 1.285.740 MM de DFN del DCF; la diferencia son CLP 25.828 MM de pasivos por arrendamiento NIIF 16).` },
        { p: `Tampoco la calidad justifica la prima. Mallplaza transa 29% sobre Cencosud Shopping, pero su EBITDA por m² es solo 1,9% mayor (ver Industria); solo al múltiplo de Parque Arauco (18,4x), que opera con 5,7x de deuda, valdría más que su precio. Todos los múltiplos, del EV/EBITDA NTM (CLP 2.914) al P/BV (CLP 3.171), quedan bajo el precio (Figura 32): confirman que la acción está cara, y la magnitud la da el DCF. Excluimos el P/E (CLP 8.644), distorsionado por la revalorización de propiedades. Puesto en precios: a la mediana chilena la acción valdría CLP 3.294 (−7%); al múltiplo de Cencosud, CLP 2.621; y solo al de Parque Arauco, CLP 3.967. Defender CLP 3.555 con múltiplos exige suponer que Mallplaza merece la valoración del par más apalancado del grupo.` },
        { h1: "LO QUE EL MERCADO TENDRÍA QUE CREER" },
        { p: `El precio implica un EV de CLP ${f.bn(K.ev_mercado_mm)} billones, ${f.pc(K.ev_mercado_vs_dcf, 0)} sobre el nuestro, y un cap rate real de ${f.pc(K.cap_mercado, 1)} (EBITDA UDM / EV, comparable con tasas reales porque las rentas se reajustan por UF), frente a ${f.pc(K.cap_dcf, 1)} en nuestro DCF, ${f.pc(K.cap_pares, 1)} en los pares chilenos y ${f.pc(K.cap_libro, 1)} a valor libro (Figura 33). El mercado paga ${f.n(K.pb_precio, 2)} veces un patrimonio que ya está a valor razonable, tasado con una tasa de descuento real de ~${f.pc(K.tasacion_real, 2)} (Nota 11); la TIR real que deja el precio, ${f.pc(TIR.firma.real, 1)}, queda bajo esa tasa: paga más que los propios tasadores. Para justificar CLP ${f.n(K.precio)} la WACC nominal tendría que ser ${f.pb(abs(K.wacc_impl_pb))} pb menor (${f.pc(K.wacc_impl, 2)}, ${f.pc(K.wacc_impl_real, 1)} real; Figura 34); incluso con la tasa de los tasadores (${f.pc(K.tasacion_real, 2)} real, ${f.pc(K.tasacion_nom, 2)} nominal), el DCF sería CLP ${f.n(e("tas").dcf)}. (La WACC implícita desplaza toda la curva de WACC; la TIR de tasa única, ${f.pc(TIR.firma.nom, 2)}, es la misma idea y también da CLP ${f.n(K.precio)}.)` },
        { h1: "POR QUÉ EL MERCADO PAGA CLP 3.555" },
        { p: `En doce meses la acción pasó de un mínimo de CLP ${f.n(K.rango_52s[0])} (10-oct-25) a un máximo de CLP ${f.n(K.rango_52s[1])} (27-abr-26), un alza de ~90% que el negocio no explica: el EBITDA creció 5–10% anual. El impulso vino de afuera. La bolsa chilena subió 56% en 2025, con un cambio de gobierno y expectativas de menores impuestos, y los malls rentaron ~48% (LarrainVial) y se revalorizaron en bloque. La inclusión en el MSCI EM Mid Cap (25-nov-25) obligó a fondos pasivos a comprar ~USD 110 MM, unas 15 veces el volumen diario (Morgan Stanley). Y los analistas extrapolaron crecimiento: JPMorgan proyecta un FFO que crece ~11% anual hasta 2028, el doble de nuestro ~${f.n(ffoCagr * 100, 0)}% (2026E–2028E), y el sector chileno transa a 18,6x FFO frente a 10,5x en Brasil. La caída a CLP 3.555 (−24% desde el máximo) coincide con resultados bajo lo esperado (EBITDA +5,2% en 1T26), el recorte del objetivo de JPMorgan y el alza del UST a 10 años a 5,22%. Es una corrección parcial: a ese precio la acción cotiza ${f.pc(K.precio_vs_dcf, 0)} sobre el DCF, ${f.pc(K.precio_vs_tasadores, 0)} sobre el valor con la tasa de los tasadores (CLP ${f.n(e("tas").dcf)}) y a ${f.n(K.pb_precio, 2)}x su valor libro. Los compradores que llevaron el precio al máximo (fondos pasivos, impulso sectorial y crecimiento extrapolado) no cambian los flujos del negocio. Las cifras atribuidas a analistas son de sus propias notas y los precios intermedios son aproximados (Figura R2).` },
        { h1: "NUESTRO VALOR FRENTE AL CONSENSO" },
        { p: `Bloomberg muestra ${K.consenso.fuentes} fuentes con una recomendación promedio de ${f.n(K.consenso.valor, 2)} (1 comprar, 10 mantener, 2 vender) y un precio objetivo a 12 meses de CLP ${f.n(K.consenso.po_12m)}, ${f.pc(abs(K.po / K.consenso.po_12m - 1), 1)} sobre el nuestro; el más bajo es el de Goldman Sachs (vender, CLP ${f.n(K.consenso.bajo)}) y el rango va de ${f.n(K.consenso.bajo)} a ${f.n(K.consenso.alto)}. Cuatro razones explican la brecha (Figura R3). La tasa es la principal: el precio exige una WACC nominal de ${f.pc(K.wacc_impl, 2)}, ${f.pb(abs(K.wacc_impl_pb))} pb bajo nuestro ${f.pc(K.wacc_t, 2)}, y como el valor terminal es ${f.pc(K.vt_ev, 0)} del EV, cada punto de tasa pesa mucho. Los múltiplos tampoco llegan: el 20% en múltiplos da CLP ${f.n(K.mult_valor)}, ${f.pc(abs(K.mult_valor / K.precio - 1), 0)} bajo el precio, así que no todo es WACC. El horizonte también cuenta: los objetivos son a 12 meses y el nuestro es al 30-jun-26; a nuestro Ke nominal de ${f.pc(K.ke_t, 2)}, CLP ${f.n(K.consenso.po_12m)} equivalen a ~CLP ${f.n(d4111, -2 + 2)} hoy, de modo que la brecha se reduce, pero no se cierra. Y el crecimiento: si crecer rinde menos que la WACC, nuestro modelo lo castiga, mientras el mercado probablemente lo valora con un retorno cercano al cap rate. Del lado del consenso, los objetivos siguen al precio (la acción subió 39% en 12 meses y los objetivos subieron con ella), 77% mantiene y solo 15% recomienda vender, lo que puede reflejar sesgo de relación con emisores sin probar que estén equivocados; no conocemos sus supuestos, solo sus objetivos.` },
        { h1: "ESCENARIOS: LO QUE TENDRÍA QUE PASAR" },
        { p: `Llevamos la tesis a sus extremos con tres escenarios definidos con las mismas palancas del tornado de Riesgos (Figura T), en vez de mover solo la tasa. Bear es todo lo que sale mal a la vez: WACC nominal +100 pb y cada palanca operacional en su mínimo histórico. Bull es todo lo que sale bien: WACC nominal −100 pb, cada palanca en su máximo histórico e impuesto de 23% (Ley de Reconstrucción). Base es la estimación central del modelo. El arriendo en mismas tiendas (precio) y las ventas de los locatarios se mueven juntos; g nominal se mantiene en ${f.pc(K.g, 1)} en los tres. Ponderados 25/50/25% (supuesto del equipo, por validar), el precio objetivo sería CLP ${f.n(K.ponderado.po)}.` },
        { t: "ESC" },
        { p: `El resultado es robusto: ni con todo a favor el precio objetivo (CLP ${f.n(e("bull").po)}) alcanza la cotización. La TIR de la firma al precio de mercado casi no cambia entre escenarios (${f.pc(TIR.esc.bear.nom, 1)}, ${f.pc(TIR.esc.base.nom, 1)} y ${f.pc(TIR.esc.bull.nom, 1)} nominal en bear, base y bull; ${f.pc(TIR.esc.bear.real, 1)}, ${f.pc(TIR.esc.base.real, 1)} y ${f.pc(TIR.esc.bull.real, 1)} real) y queda siempre bajo la WACC de cada uno (${f.pb(TIR.esc.bear.brecha_nom)}, ${f.pb(TIR.esc.base.brecha_nom)} y ${f.pb(TIR.esc.bull.brecha_nom)} pb nominales): ni el bull deja margen de seguridad. El APV (CLP ${f.n(K.apv)}), una Rf basada en el bono en pesos (~CLP ${f.n(K.rf_pesos_po)}) y otros objetivos de deuda (DCF de CLP ${f.n(K.deuda_tabla.filas[0][1])} a ${f.n(Math.max(...K.deuda_tabla.filas.flatMap((r) => r.slice(1))))}) llevan a la misma conclusión (Anexo 18).` },
        { p: `El APV también dice cuánto vale de verdad la deuda. De sus CLP ${f.n(K.apv)} por acción, CLP ${f.n(K.apv_sin_deuda)} corresponden a la empresa sin deuda y CLP ${f.n(K.apv_escudos)} a los escudos fiscales de la deuda proyectada: apalancarse hasta 3,5x agrega valor, pero ni sumándolo se acerca al precio. La elección de la tasa libre de riesgo es la conservadora: usar el bono nominal en pesos (5,43%) y además sumar el riesgo país contaría dos veces el riesgo Chile, y aun así el precio objetivo solo subiría a ~CLP ${f.n(K.rf_pesos_po)}, ${f.pc(abs(K.rf_pesos_po / K.precio - 1), 0)} bajo el precio. Con un dividendo esperado de ~CLP ${f.n(K.dividendo_27, 0)} por acción (${f.pc(K.dividend_yield, 1)}), el retorno total esperado es ${f.pc(K.ret_total, 1)}.` },
        { p: `Así llegamos a CLP ${f.n(K.po)} (80% × ${f.n(K.dcf)} + 20% × ${f.n(K.mult_valor)}): ${f.n(K.ev_ebitda_po, 1)}x EBITDA, un cap rate real de ${f.pc(K.cap_po_real, 1)} y ${f.n(K.pb_po, 2)}x el valor libro. Llevar el DCF al 30-sep-26 lo subiría a ~CLP ${f.n(po30s)}, sin cambiar la recomendación. El catalizador es el mismo que sostiene la tesis: con el UST 10Y nominal en 5,22%, máximo desde 2002, las tasas presionan los cap rates, y cada nueva tasación los acerca a nuestro valor. Nos equivocaríamos si los cap rates se comprimen aún más por la demanda institucional por activos defensivos, o si el mercado sostiene una prima estructural por los activos Tier A (ver Riesgos de inversión). Vigilaremos la tasación de la Nota 11 en cada cierre, el spread del bono UF frente a su cupón real de 3,6% (con la tasa efectiva real de 4,33% de la última emisión, la WACC nominal subiría 12 pb y el precio objetivo bajaría a CLP ${f.n(kdPO)}), la rebaja del impuesto corporativo a 23% (+${f.pc(e("bull").po && K.supuestos_indiv[0][1] / K.supuestos_base, 1).replace("%", "")}% al precio objetivo, aún no incluida) y la clasificación AAA, que probablemente quedaría bajo presión con 3,5x de DFN/EBITDA.` },
      ],
      figs1: [
        ["Figura 27:", "Ningún método justifica el precio actual (CLP por acción)", "V1_football", "Rango de 52 semanas intradía (01-10-25 a 30-09-26; mínimo 10-10-25, máximo 27-04-26). Fuente: análisis del equipo; Bloomberg."],
        ["Figura 28:", "A CLP 3.555 la firma rinde casi lo mismo que su deuda (tasas reales, UF)", "V2_tasas", "Tasas reales en UF. Fuente: BCCh (30-06-26); Mallplaza; análisis del equipo."],
        ["Figura 29:", `Con todos los supuestos fuertes a favor el objetivo llega a CLP ${f.n(cascadaFin, 0)}, aún ${f.pc(abs(cascadaFin / K.precio - 1), 0)} bajo el precio`, "V13_supuestos_cascada", "Cascada acumulada en el orden mostrado; la tabla da el efecto de cada supuesto solo. Precio objetivo = 80% DCF + 20% múltiplos. Fuente: réplica del DCF v4; análisis del equipo."],
        ["Figura 30:", "Crecer bajo la WACC destruye valor: g real = 0%", "V3_value_driver", "Arriba: valor DCF según g nominal. Abajo: valor terminal relativo según el RONIC. Fuente: análisis del equipo."],
      ],
      figs2: [
        ["Figura 31:", "Chile y Brasil cobran la misma prima: los múltiplos difieren por las tasas", "V7_multiplos", "Bono real: UF 10 años (BCCh) y NTN-B 2035 (8,08%) al 30-06-26. Spread = cap rate (1 / EV/EBITDA) − bono real. IRSA se omite (NIC 29). Fuente: Bloomberg; BCCh; análisis del equipo."],
        ["Figura 32:", "Valor implícito por múltiplo de cada par vs DCF y precio (CLP por acción)", "V9_pares", "Precio objetivo = 80% DCF + 20% EV/EBITDA LTM. P/E excluido (incluye revalorización). Fuente: Bloomberg (30-09-26); análisis del equipo."],
        ["Figura 33:", `El mercado paga ${f.pc(K.cap_mercado, 1)}; nuestros flujos valen ${f.pc(K.cap_dcf, 1)} (cap rate real)`, "V5_cap_rate", "Cap rate = EBITDA UDM / EV, comparable con tasas reales (rentas en UF). Gran Plaza: hecho posterior, no entra al modelo. Fuente: Mallplaza; Bloomberg; DF; análisis del equipo."],
        ["Figura 34:", `El precio exige una WACC nominal ${f.pb(abs(K.wacc_impl_pb))} pb menor`, "V6_dcf_inverso", "WACC nominal terminal; todos los períodos se desplazan en paralelo. Fuente: análisis del equipo."],
      ],
    },
    // ------------------------------------------------------------------ inglés
    en: {
      lead: `We recommend SELL on Mallplaza with a target price of CLP ${f.n(K.po)} per share, ${f.pc(abs(K.po_vs), 1)} below the CLP ${f.n(K.precio)} close of 30-Sep-26 (${f.pc(K.ret_total, 1)} total return including dividends). Our target sits even below the stock's 52-week low (CLP ${f.n(K.rango_52s[0])}).`,
      p1: [
        { h1: "A PRICE NO METHOD REACHES" },
        { p: `In twelve months the stock rose from CLP ${f.n(K.rango_52s[0])} to ${f.n(K.rango_52s[1])} and now trades at CLP ${f.n(K.precio)}. None of our methods reaches that price: the DCF ranges from CLP ${f.n(K.football.dcf_100[0])} to ${f.n(K.football.dcf_100[1])} even with nominal WACC ±100 bp and nominal g between 2.5% and 4.0%, and the most favourable multiples fall short too (Figure 27). We give the DCF an 80% weight because Mallplaza is, at heart, a rent collector: 81.4% of revenue is rent and 93% of that is fixed. The 20% on multiples tests the model against what the market pays today, but with caution: Chile has only two direct peers, and neither captures the company's expansion plan or debt path.` },
        { p: `Figure 27 sums up the thesis in one image. The APV, which values the firm without debt and adds the tax shields separately, gives CLP ${f.n(K.apv)}, only ${f.pc(K.apv / K.dcf - 1, 0)} above the DCF: the result does not depend on how we model financing. Multiples range from CLP ${f.n(K.football.mult_set_cl[0])} (common-set median) to ${f.n(K.football.mult_set_cl[1])} (Chilean median), and NTM EV/EBITDA and EV/EBIT fall between CLP ${f.n(K.football.ntm_ebit[0])} and ${f.n(K.football.ntm_ebit[1])}. Everything lands to the left of the price; only the stock's own one-year trading range reaches it. Even the Chilean median multiple, the most favourable case for the stock, sits ${f.pc(abs(K.football.mult_set_cl[1] / K.precio - 1), 0)} below the price.` },
        { h1: "THE STORY IS IN THE DISCOUNT RATE" },
        { p: `We project the firm's free cash flow (FCFF) in nominal CLP from 30-Jun-26, with an explicit horizon to 2031E and a terminal value that explains ${f.pc(K.vt_ev, 0)} of EV (Appendix 15). The CLP ${f.n(K.dcf)} per share is CLP ${f.n(K.ps_exp)} of explicit cash flows and CLP ${f.n(K.ps_vt)} of terminal value, less CLP ${f.n(K.ps_deuda)} of net debt and minorities: the result depends, above all, on the discount rate.` },
        { p: `That rate moves with the capital structure. Mallplaza uses its debt capacity to grow, as in 2024 after buying Open Plaza Peru (3.78x): we assume net debt/EBITDA rises from ${f.n(K.dfn_ebitda0, 2)}x to ${f.n(K.dfn_ebitda_obj, 1)}x by 2031, with 25 bp more real cost per turn, and that the new debt (CLP ${f.bn(dNueva)} trillion) funds all capex while operating cash is distributed to shareholders. Nominal WACC thus moves from ${f.pc(K.wacc_2s, 2)} in 2H26E to ${f.pc(K.wacc_t, 2)} at the terminal (${f.pc(K.wacc_2s_real, 2)} and ${f.pc(K.wacc_t_real, 2)} real): a nominal Ke of ${f.pc(K.ke_t, 2)} (${f.pc(K.ke_t_real, 2)} real; USD Rf of ${f.pc(K.rf, 2)}, re-levered beta of ${f.n(K.beta_t, 2)} from a six-peer median of ${f.n(K.beta_u, 2)}, ERP ${f.pc(K.erp, 2)} and a revenue-weighted CRP of ${f.pc(K.crp, 2)}) and a nominal after-tax Kd of ${f.pc(K.kd_t_at, 2)}, based on the ${f.pc(K.kd_real, 1)} real (UF) coupon of the latest issue (Appendix 19).` },
        { p: `We build Ke in dollars because its three inputs are in that currency and nominal: the US Treasury Rf, the implied market risk premium published by Damodaran and country risk, which we weight by revenue. We then convert it to pesos with the differential between expected inflation in Chile (3.0%, the central bank target) and in the US (2.24%, 10-year breakeven). Beta is unlevered with Hamada (six regional peers) and re-levered each period (${f.n(K.beta_2, 2)} in 2H26E, ${f.n(K.beta_t, 2)} at the terminal).` },
        { p: `The first signal is the asset (firm) IRR: the single rate that equates FCFF and terminal value to the enterprise value the market pays at CLP ${f.n(K.precio)} (EV of CLP ${f.bn(K.ev_mercado_mm)} trillion). It is ${f.pc(TIR.firma.nom, 2)} nominal (${f.pc(TIR.firma.real, 2)} real in UF), ${f.pb(TIR.firma.brecha_nom)} bp below the nominal WACC (${f.pb(TIR.firma.brecha_real)} bp in real terms) and only ~${pbReal(K)} real bp above the real cost of its debt (Figure 28).` },
        { t: "TIR" },
        { h1: "GROWTH DOES NOT RESCUE THE PRICE" },
        { p: `We are not pessimistic about operations. We project a 79.7% EBITDA margin in 2026E (excluding revaluations, below the 80.5% LTM), a cash tax rate converging from 16.8% to 27% by 2030, the company's full dated pipeline (${f.n(K.pipeline_m2)} m² and USD ${f.n(K.pipeline_usd_mm)} MM, including ${f.n(K.otros_m2)} m² of “other projects” in Chile opening in 2028) and, from 2029, ${f.n(K.gla_anual)} new m² per year, the historical organic pace. The consensus of 13 analysts expects 12-month EBITDA only ~3% above ours: the disagreement with the market is not in the cash flows.` },
        { p: `Capex follows the company's plan and is split into maintenance and IT (5.5% of revenue, CLP ${rng(mant)} bn per year) and incremental capex: the pipeline under way (CLP ${f.mm(pipe, 0)} bn in 2H26E–2028E) and continuous expansion (CLP ${rng(expc)} bn per year from 2028, at USD ${f.n(K.costo_usd_m2)} per m² and a revenue ramp of 35%, 90% and 100%). Total capex peaks at CLP ${f.mm(capexTot[imax], 0)} bn in ${anio} and settles near ${f.pc(capexIng.reduce((a, b) => a + b, 0) / 3, 0)} of revenue from 2029E (Figure F7). Working capital (15.6% of revenue) requires CLP ${f.n(Math.min(...ct) / 1000, 1)}–${f.n(Math.max(...ct) / 1000, 1)} bn per year and, if it were zero, the target would rise only ${f.pc(ctCero / 100, 1)} (Figure 29; Appendix 16).` },
        { p: `Two assumptions deserve an explanation. The cash tax rate starts at 16.8% because the company currently uses tax goodwill and accumulated losses; we assume those shields run out and the rate reaches 27% in 2030. It is real cash savings (lower current tax), not accounting: CLP ${f.n(K.escudo_ps, 0)} per share undiscounted; without it the target falls ${f.n(goodwillPct, 1)}% (Figure 29). And working capital grows with revenue, not with new m².` },
        { p: `Price and sales. For a rental operator the price is rent per m², and tenants' sales reach revenue only through variable rent (${f.pc(S.share_var, 1)} of revenue). So 1 pp more nominal same-store rent growth in 2027–28 adds CLP ${f.n(S.ssr_1pp, 0)} to the DCF value per share, ${f.n(ratioPS, 0)} times what 1 pp more tenant-sales growth adds (CLP ${f.n(S.sss_1pp, 1)}); 1 pp more real rent growth in 2029–31 adds CLP ${f.n(S.ssr_lp_1pp, 0)}. Better prices can translate into higher sales and variable rent when occupancy and traffic sustain them, so in the bull case we move both levers at once (rent +9.4%, sales +9.9%): even so, the target stays ${f.pc(abs(e("bull").vs), 0)} below the price.` },
        { p: `The problem is the return on growth. Each new m² yields ${f.pc(K.yield_costo, 1)} real before tax on its cost (expansion mix: ${f.pc(K.mix_chile, 0)} Chile, ${f.pc(1 - K.mix_chile, 0)} Peru), a real after-tax RONIC of ${f.pc(K.ronic, 1)}, below a real WACC of ${f.pc(K.wacc_t_real, 1)}. The IRR of a new m², with capex, ramp, maintenance and working capital, is ${f.pc(TP.real, 2)} real (${f.pc(TP.nom, 2)} nominal): ${f.pb(TP.brecha_real)} bp below the real WACC and ${f.pb(TP.brecha_nom)} bp below the nominal one; to match it, revenue per m² would have to be ${f.n(TP.escala_igualar_wacc, 2)} times the model's. Expansion adds revenue but not value: that is why terminal value grows only with inflation (nominal g of ${f.pc(K.g, 1)}, 0% real) and a higher g reduces value (Figure 30). Assuming more growth would not close the gap with the price; it would widen it. The explicit horizon therefore includes the capex and maturation of projects opening through 2032 (${f.n(K.m2_maduro)} m² mature in the terminal year), but from there terminal incremental capex is zero and only maintenance remains.` },
        { h1: "WHY EXPAND IF IT DOES NOT CREATE VALUE?" },
        { p: `If growth earns less than the cost of capital, what pushes management to keep going? We put forward four hypotheses, to be verified against the annual report and financial statements. First, accounting versus economics: debt is 100% UF-denominated at ~3.6% real, below what a new asset yields, so every debt-financed project improves FFO, EBITDA and profit even if it does not cover the return required on total capital. Second, revaluation: under IAS 40 appraisals use real rates of 5.5–6.4%, below the WACC, and each new asset is appraised above its cost and generates accounting profit. Third, the controlling shareholder: if the group (Falabella, to be confirmed) has anchor stores or other businesses in those malls, a new m² serves the group even if it earns little for Plaza, an agency conflict with minority shareholders (to be verified in the related-party notes). Fourth, compensation: if bonuses depend on GLA or EBITDA rather than ROIC, expanding is rational for management (to be verified). There are also defensible strategic reasons, such as scarce land and network advantages. It is a corporate-governance and capital-allocation risk, and it does not contradict that the business is good. The break-even for expansion is a real WACC of ${f.pc(K.ronic, 1)} (${f.pc((1 + K.ronic) * (1 + K.pi) - 1, 1)} nominal); the WACC implied by the price (${f.pc(K.wacc_impl, 2)} nominal, ${f.pc(K.wacc_impl_real, 1)} real) is below that level: if the market were right, expanding would create value.` },
      ],
      p2: [
        { h1: "PEERS CONFIRM THE DIRECTION, NOT THE MAGNITUDE" },
        { p: `Mallplaza trades at 16.8x EV/EBITDA, above the Chilean median (15.7x) and far above Brazilian peers (9.0x). The gap with Brazil is not about quality but about rates: with local real bonds of 2.5% in Chile and 8.1% in Brazil (NTN-B), the cap-rate spread (EBITDA/EV yield; with UF-indexed rents it is compared with real rates) over the local rate is similar in both countries, 385 bp in Chile and 302 bp in Brazil (Figure 31). That is why we weight the Chilean median 70% and the common-set median 30% (which includes IRSA; we exclude Fibra Danhos because of its FIBRA regime): ${f.n(K.mult_x, 1)}x, which leads to CLP ${f.n(K.mult_valor)} per share. The weighting matters little: from 0% to 100% Chile, the target price only moves from CLP 1,916 to 2,144 (Appendix 17).` },
        { p: `We chose the set with the same criterion as beta. IRSA stays with caution, because it reports under IAS 29 and its NTM consensus has a single analyst; Fibra Danhos is out because, as a FIBRA, it must distribute 95% of its taxable income and has no beta in the WACC. We use EV/EBITDA because it is neutral to leverage and to revaluation (IAS 40), and measure everyone with Bloomberg net debt (CLP 1,311,569 MM for Mallplaza, close to the CLP 1,285,740 MM net financial debt in the DCF; the difference is CLP 25,828 MM of IFRS 16 lease liabilities).` },
        { p: `Quality does not justify the premium either. Mallplaza trades 29% above Cencosud Shopping, yet its EBITDA per m² is only 1.9% higher (see Industry); only at Parque Arauco's multiple (18.4x), which runs 5.7x leverage, would it be worth more than its price. Every multiple, from NTM EV/EBITDA (CLP 2,914) to P/BV (CLP 3,171), sits below the price (Figure 32): they confirm the stock is expensive, and the DCF gives the magnitude. We exclude P/E (CLP 8,644), distorted by property revaluation. In prices: at the Chilean median the stock would be worth CLP 3,294 (−7%); at Cencosud's multiple, CLP 2,621; and only at Parque Arauco's, CLP 3,967. Defending CLP 3,555 with multiples requires assuming Mallplaza deserves the valuation of the most leveraged peer in the group.` },
        { h1: "WHAT THE MARKET WOULD HAVE TO BELIEVE" },
        { p: `The price implies an EV of CLP ${f.bn(K.ev_mercado_mm)} trillion, ${f.pc(K.ev_mercado_vs_dcf, 0)} above ours, and a real cap rate of ${f.pc(K.cap_mercado, 1)} (LTM EBITDA / EV, comparable with real rates because rents are UF-indexed), against ${f.pc(K.cap_dcf, 1)} in our DCF, ${f.pc(K.cap_pares, 1)} for Chilean peers and ${f.pc(K.cap_libro, 1)} at book value (Figure 33). The market pays ${f.n(K.pb_precio, 2)} times an equity that is already at fair value, appraised with a real discount rate of ~${f.pc(K.tasacion_real, 2)} (Note 11); the real IRR the price leaves, ${f.pc(TIR.firma.real, 1)}, is below that rate: it pays more than the appraisers themselves. To justify CLP ${f.n(K.precio)}, nominal WACC would have to be ${f.pb(abs(K.wacc_impl_pb))} bp lower (${f.pc(K.wacc_impl, 2)}, ${f.pc(K.wacc_impl_real, 1)} real; Figure 34); even with the appraisers' rate (${f.pc(K.tasacion_real, 2)} real, ${f.pc(K.tasacion_nom, 2)} nominal), the DCF would be CLP ${f.n(e("tas").dcf)}. (The implied WACC shifts the whole WACC curve; the single-rate IRR, ${f.pc(TIR.firma.nom, 2)}, is the same idea and also gives CLP ${f.n(K.precio)}.)` },
        { h1: "WHY THE MARKET PAYS CLP 3,555" },
        { p: `In twelve months the stock went from a low of CLP ${f.n(K.rango_52s[0])} (10-Oct-25) to a high of CLP ${f.n(K.rango_52s[1])} (27-Apr-26), a ~90% rise the business does not explain: EBITDA grew 5–10% a year. The push came from outside. The Chilean market rose 56% in 2025, with a change of government and expectations of lower taxes, and malls returned ~48% (LarrainVial) and re-rated together. MSCI EM Mid Cap inclusion (25-Nov-25) forced passive funds to buy ~USD 110 MM, some 15 times daily volume (Morgan Stanley). And analysts extrapolated growth: JPMorgan projects FFO growing ~11% a year to 2028, double our ~${f.n(ffoCagr * 100, 0)}% (2026E–2028E), and the Chilean sector trades at 18.6x FFO against 10.5x in Brazil. The fall to CLP 3,555 (−24% from the high) coincides with weaker-than-expected results (EBITDA +5.2% in 1Q26), JPMorgan's target cut and the 10-year UST rising to 5.22%. It is a partial correction: at that price the stock trades ${f.pc(K.precio_vs_dcf, 0)} above the DCF, ${f.pc(K.precio_vs_tasadores, 0)} above the value at the appraisers' rate (CLP ${f.n(e("tas").dcf)}) and at ${f.n(K.pb_precio, 2)}x book value. The buyers who took the price to its high (passive funds, sector momentum and extrapolated growth) do not change the business's cash flows. Figures attributed to analysts come from their own notes and intermediate prices are approximate (Figure R2).` },
        { h1: "OUR VALUE VERSUS THE CONSENSUS" },
        { p: `Bloomberg shows ${K.consenso.fuentes} sources with an average recommendation of ${f.n(K.consenso.valor, 2)} (1 buy, 10 hold, 2 sell) and a 12-month target price of CLP ${f.n(K.consenso.po_12m)}, ${f.pc(abs(K.po / K.consenso.po_12m - 1), 1)} above ours; the lowest is Goldman Sachs (sell, CLP ${f.n(K.consenso.bajo)}) and the range runs from ${f.n(K.consenso.bajo)} to ${f.n(K.consenso.alto)}. Four reasons explain the gap (Figure R3). The discount rate is the main one: the price requires a nominal WACC of ${f.pc(K.wacc_impl, 2)}, ${f.pb(abs(K.wacc_impl_pb))} bp below our ${f.pc(K.wacc_t, 2)}, and since terminal value is ${f.pc(K.vt_ev, 0)} of EV, each point of rate weighs heavily. Multiples do not get there either: the 20% on multiples gives CLP ${f.n(K.mult_valor)}, ${f.pc(abs(K.mult_valor / K.precio - 1), 0)} below the price, so it is not all WACC. The horizon also counts: targets are 12-month and ours is as of 30-Jun-26; at our nominal Ke of ${f.pc(K.ke_t, 2)}, CLP ${f.n(K.consenso.po_12m)} is worth ~CLP ${f.n(d4111, 0)} today, so the gap narrows but does not close. And growth: if growth earns less than the WACC, our model penalises it, while the market probably values it at a return close to the cap rate. On the consensus side, targets follow the price (the stock rose 39% in 12 months and targets rose with it), 77% hold and only 15% recommend selling, which may reflect issuer-relationship bias without proving they are wrong; we do not know their assumptions, only their targets.` },
        { h1: "SCENARIOS: WHAT WOULD HAVE TO HAPPEN" },
        { p: `We push the thesis to its extremes with three scenarios defined with the same levers as the Risks tornado (Figure T), instead of moving only the discount rate. Bear is everything going wrong at once: nominal WACC +100 bp and every operating lever at its historical minimum. Bull is everything going right: nominal WACC −100 bp, every lever at its historical maximum and a 23% tax rate (Reconstruction Law). Base is the model's central estimate. Same-store rent (price) and tenants' sales move together; nominal g stays at ${f.pc(K.g, 1)} in all three. Weighted 25/50/25% (team assumption, to be validated), the target price would be CLP ${f.n(K.ponderado.po)}.` },
        { t: "ESC" },
        { p: `The result is robust: even with everything in its favour the target price (CLP ${f.n(e("bull").po)}) does not reach the quote. The firm's IRR at the market price barely changes across scenarios (${f.pc(TIR.esc.bear.nom, 1)}, ${f.pc(TIR.esc.base.nom, 1)} and ${f.pc(TIR.esc.bull.nom, 1)} nominal in bear, base and bull; ${f.pc(TIR.esc.bear.real, 1)}, ${f.pc(TIR.esc.base.real, 1)} and ${f.pc(TIR.esc.bull.real, 1)} real) and always sits below each one's WACC (${f.pb(TIR.esc.bear.brecha_nom)}, ${f.pb(TIR.esc.base.brecha_nom)} and ${f.pb(TIR.esc.bull.brecha_nom)} nominal bp): not even the bull leaves a margin of safety. The APV (CLP ${f.n(K.apv)}), an Rf based on the peso bond (~CLP ${f.n(K.rf_pesos_po)}) and other debt targets (DCF of CLP ${f.n(K.deuda_tabla.filas[0][1])} to ${f.n(Math.max(...K.deuda_tabla.filas.flatMap((r) => r.slice(1))))}) lead to the same conclusion (Appendix 18).` },
        { p: `The APV also says how much the debt is really worth. Of its CLP ${f.n(K.apv)} per share, CLP ${f.n(K.apv_sin_deuda)} is the unlevered firm and CLP ${f.n(K.apv_escudos)} the tax shields of the projected debt: levering up to 3.5x adds value, but even adding it does not approach the price. Our risk-free choice is the conservative one: using the nominal peso bond (5.43%) and also adding country risk would count Chile risk twice, and even so the target price would only rise to ~CLP ${f.n(K.rf_pesos_po)}, ${f.pc(abs(K.rf_pesos_po / K.precio - 1), 0)} below the price. With an expected dividend of ~CLP ${f.n(K.dividendo_27, 0)} per share (${f.pc(K.dividend_yield, 1)}), the expected total return is ${f.pc(K.ret_total, 1)}.` },
        { p: `That is how we get to CLP ${f.n(K.po)} (80% × ${f.n(K.dcf)} + 20% × ${f.n(K.mult_valor)}): ${f.n(K.ev_ebitda_po, 1)}x EBITDA, a real cap rate of ${f.pc(K.cap_po_real, 1)} and ${f.n(K.pb_po, 2)}x book value. Rolling the DCF forward to 30-Sep-26 would lift it to ~CLP ${f.n(po30s)}, without changing the recommendation. The catalyst is the one that holds the thesis together: with the nominal 10Y UST at 5.22%, the highest since 2002, rates pressure cap rates, and each new appraisal moves them toward our value. We would be wrong if cap rates compress further on institutional demand for defensive assets, or if the market sustains a structural premium for Tier A assets (see Investment Risks). We will watch the Note 11 appraisal at each close, the spread on the company's UF bond versus its 3.6% real coupon (at the 4.33% real effective rate of the latest issue, nominal WACC would rise 12 bp and the target price would fall to CLP ${f.n(kdPO)}), the cut in corporate tax to 23% (+${f.n(K.supuestos_indiv[0][1] / K.supuestos_base * 100, 1)}% to the target price, not yet included) and the AAA rating, which would probably come under pressure at 3.5x net debt/EBITDA.` },
      ],
      figs1: [
        ["Figure 27:", "No method justifies the current price (CLP per share)", "V1_football", "Intraday 52-week range (01-10-25 to 30-09-26; low 10-10-25, high 27-04-26). Source: Team analysis; Bloomberg."],
        ["Figure 28:", "At CLP 3,555 the firm earns almost the same as its debt (real rates, UF)", "V2_tasas", "Real rates in UF. Source: Central Bank of Chile (30-06-26); Mallplaza; Team analysis."],
        ["Figure 29:", `With every strong assumption in our favor the target reaches CLP ${f.n(cascadaFin, 0)}, still ${f.pc(abs(cascadaFin / K.precio - 1), 0)} below the price`, "V13_supuestos_cascada", "Cumulative waterfall in the order shown; the table gives each assumption's effect alone. Target price = 80% DCF + 20% multiples. Source: DCF v4 replica; Team analysis."],
        ["Figure 30:", "Growing below the WACC destroys value: real g = 0%", "V3_value_driver", "Top: DCF value by nominal g. Bottom: relative terminal value by RONIC. Source: Team analysis."],
      ],
      figs2: [
        ["Figure 31:", "Chile and Brazil charge the same premium: multiples differ because of rates", "V7_multiplos", "Real bond: 10-year UF (BCCh) and NTN-B 2035 (8.08%) at 30-06-26. Spread = cap rate (1 / EV/EBITDA) − real bond. IRSA omitted (IAS 29). Source: Bloomberg; BCCh; Team analysis."],
        ["Figure 32:", "Implied value per peer multiple vs DCF and price (CLP per share)", "V9_pares", "Target price = 80% DCF + 20% LTM EV/EBITDA. P/E excluded (includes revaluation). Source: Bloomberg (30-09-26); Team analysis."],
        ["Figure 33:", `The market pays ${f.pc(K.cap_mercado, 1)}; our cash flows are worth ${f.pc(K.cap_dcf, 1)} (real cap rate)`, "V5_cap_rate", "Cap rate = LTM EBITDA / EV, comparable with real rates (UF rents). Gran Plaza: subsequent event, not in the model. Source: Mallplaza; Bloomberg; DF; Team analysis."],
        ["Figure 34:", `The price requires a nominal WACC ${f.pb(abs(K.wacc_impl_pb))} bp lower`, "V6_dcf_inverso", "Terminal nominal WACC; all periods shift in parallel. Source: Team analysis."],
      ],
    },
  };
  return T[lang];
}

// ---------------------------------------------------------------- tablas (TIR y escenarios)
function tablaTIR(lang) {
  const { K, f } = cifras(lang);
  const es = lang === "es", TIR = K.tir, TP = K.tir_proyecto;
  const proyecto = { nom: TP.nom, real: TP.real, costo_nom: TP.wacc_nom, costo_real: TP.wacc_real, brecha_nom: TP.brecha_nom, brecha_real: TP.brecha_real };
  const T = { ...TIR, proyecto };
  const sg = (x) => (x < 0 ? "−" : "+") + f.pb(x);
  const fila = (nombre, k) => [nombre, f.pc(T[k].nom, 2), f.pc(T[k].real, 2), `${f.pc(T[k].costo_nom, 2)} / ${f.pc(T[k].costo_real, 2)}`, `${sg(T[k].brecha_nom)} / ${sg(T[k].brecha_real)} ${es ? "pb" : "bp"}`];
  return { anchos: [2300, 740, 640, 1800, 1420], derecha: [1, 2, 3, 4], destacar: [3],
    titulo: es ? "TIR del activo (firma) y del proyecto nuevo frente a la WACC: nominal CLP y real (UF)" : "Asset (firm) and new-project IRR vs WACC: nominal CLP and real (UF)",
    cols: es ? ["Compra al precio de", "Nominal", "Real", "WACC nom./real", "Brecha nom./real"] : ["Buying at the price of", "Nominal", "Real", "WACC nom./real", "Gap nom./real"],
    filas: [fila(es ? `Mercado: CLP ${f.n(K.precio)}` : `Market: CLP ${f.n(K.precio)}`, "firma_objetivo" && "firma"),
      fila(es ? `Nuestro objetivo: CLP ${f.n(K.po)}` : `Our target: CLP ${f.n(K.po)}`, "firma_objetivo"),
      fila(es ? `Nuestro DCF: CLP ${f.n(K.dcf)}` : `Our DCF: CLP ${f.n(K.dcf)}`, "firma_dcf"),
      fila(es ? "Proyecto nuevo: 1 m² (cohorte)" : "New project: 1 m² (cohort)", "proyecto")],
    nota: es ? `TIR del activo: tasa única que iguala el FCFF y el valor terminal al valor de empresa pagado; al valor DCF coincide con la WACC. Proyecto nuevo: flujo de 1 m² con el costo, la rampa y el margen de la expansión, mantención y capital de trabajo. Real = (1 + nom.) / (1 + ${f.pc(K.pi, 1)}) − 1. La WACC implícita de la Figura 34 (${f.pc(K.wacc_impl, 2)}) desplaza toda la curva de WACC y la TIR de tasa única es ${f.pc(TIR.firma.nom, 2)}: dos lecturas de la misma idea. Fuente: modelo v4, hojas TIR_Implicita y TIR_Proyecto.`
             : `Asset IRR: the single rate that equates FCFF and terminal value to the enterprise value paid; at the DCF value it equals the WACC. New project: cash flow of 1 m² with the expansion cost, ramp and margin, maintenance and working capital. Real = (1 + nom.) / (1 + ${f.pc(K.pi, 1)}) − 1. The implied WACC in Figure 34 (${f.pc(K.wacc_impl, 2)}) shifts the whole WACC curve and the single-rate IRR is ${f.pc(TIR.firma.nom, 2)}: two readings of the same idea. Source: model v4, TIR_Implicita and TIR_Proyecto sheets.` };
}

function tablaEscenarios(lang) {
  const { K, f } = cifras(lang);
  const es = lang === "es", E = K.esc, P = K.esc_param, R = P.rangos, TIR = K.tir;
  const pb = es ? "pb" : "bp";
  const sg = (x) => (x < 0 ? "−" : "+") + f.pb(x);
  const wacc = (d) => `${d > 0 ? "+" : "−"}100 ${pb} (${f.pc(K.wacc_t + d, 2)}; ${f.pc((1 + K.wacc_t + d) / (1 + K.pi) - 1, 2)} ${es ? "real" : "real"})`;
  const filas = [
    [es ? "WACC nominal terminal (todos los períodos)" : "Terminal nominal WACC (all periods)", wacc(P.dw_bear), `${f.pc(K.wacc_t, 2)} (${f.pc(K.wacc_t_real, 2)} ${es ? "real" : "real"})`, wacc(-P.dw_bear)],
    [es ? "Margen EBITDA (mín. / máx. histórico trimestral)" : "EBITDA margin (historical quarterly min / max)", f.pc(P.m_lo, 1), f.pc(P.margen26, 1) + " (2026E)", f.pc(P.m_hi, 1)],
    [es ? "Ocupación consolidada" : "Consolidated occupancy", f.pc(R["Ocupación"][1], 1), f.pc(R["Ocupación"][0], 1), f.pc(R["Ocupación"][2], 1)],
    [es ? "Arriendo en mismas tiendas 2027–28 (precio, nominal)" : "Same-store rent 2027–28 (price, nominal)", f.pc(R["Same-store rent growth (SSR)"][1], 1), f.pc(R["Same-store rent growth (SSR)"][0], 1), f.pc(R["Same-store rent growth (SSR)"][2], 1)],
    [es ? `Ventas de locatarios 2027–28 (renta variable, ${f.pc(P.share_var, 1)} del ingreso)` : `Tenant sales 2027–28 (variable rent, ${f.pc(P.share_var, 1)} of revenue)`, f.pc(R["Same-store sales growth (SSS)"][1], 1), f.pc(R["Same-store sales growth (SSS)"][0], 1), f.pc(R["Same-store sales growth (SSS)"][2], 1)],
    [es ? "Crecimiento real del arriendo 2029–31" : "Real rent growth 2029–31", es ? "piso Nota 11" : "Note 11 floor", es ? "modelo" : "model", es ? "techo Nota 11" : "Note 11 ceiling"],
    [es ? "Capex de mantención + TI (% de ingresos)" : "Maintenance + IT capex (% of revenue)", "6,6%".replace(",", es ? "," : "."), f.pc(K.mant_pct, 1), "4,8%".replace(",", es ? "," : ".")],
    [es ? "Impuesto de largo plazo" : "Long-run tax rate", "27%", es ? "16,8% → 27%" : "16.8% → 27%", "23%"],
    [es ? "Valor DCF / precio objetivo 80/20 (CLP)" : "DCF value / 80/20 target price (CLP)", `${f.n(E.bear.dcf)} / ${f.n(E.bear.po)}`, `${f.n(E.base.dcf)} / ${f.n(E.base.po)}`, `${f.n(E.bull.dcf)} / ${f.n(E.bull.po)}`],
    [es ? `Precio objetivo vs CLP ${f.n(K.precio)}` : `Target price vs CLP ${f.n(K.precio)}`, f.pc(E.bear.vs, 1), f.pc(E.base.vs, 1), f.pc(E.bull.vs, 1)],
    [es ? "TIR de la firma al precio (nom.) / brecha vs WACC" : "Firm IRR at the price (nom.) / gap vs WACC", `${f.pc(TIR.esc.bear.nom, 2)} / ${sg(TIR.esc.bear.brecha_nom)} ${pb}`, `${f.pc(TIR.esc.base.nom, 2)} / ${sg(TIR.esc.base.brecha_nom)} ${pb}`, `${f.pc(TIR.esc.bull.nom, 2)} / ${sg(TIR.esc.bull.brecha_nom)} ${pb}`],
    [es ? "Probabilidad (supuesto del equipo)" : "Probability (team assumption)", "25%", "50%", "25%"],
  ];
  return { anchos: [2700, 1750, 1650, 1750], derecha: [1, 2, 3], destacar: [8, 9],
    titulo: es ? "Escenarios: bear (todo sale mal), base (central) y bull (todo sale bien)" : "Scenarios: bear (everything goes wrong), base (central) and bull (everything goes right)",
    cols: es ? ["Supuesto (todos a la vez)", "Bear", "Base", "Bull"] : ["Assumption (all at once)", "Bear", "Base", "Bull"], filas,
    nota: es ? `Las palancas operacionales son los extremos históricos del tornado de Riesgos; WACC y g nominales; arriendo (precio) y ventas se mueven juntos. g nominal terminal ${f.pc(K.g, 1)} en los tres. Ponderado 25/50/25%: DCF CLP ${f.n(K.ponderado.dcf)}, precio objetivo CLP ${f.n(K.ponderado.po)} (${f.pc(K.ponderado.vs, 1)}). Fuente: réplica del DCF v4 (Anexo 18); análisis del equipo.`
             : `Operating levers are the historical extremes of the Risks tornado; nominal WACC and g; rent (price) and sales move together. Terminal nominal g ${f.pc(K.g, 1)} in all three. Weighted 25/50/25%: DCF CLP ${f.n(K.ponderado.dcf)}, target price CLP ${f.n(K.ponderado.po)} (${f.pc(K.ponderado.vs, 1)}). Source: DCF v4 replica (Appendix 18); Team analysis.` };
}

module.exports = { calcular, tablaTIR, tablaEscenarios };
